BoundedContext Lending {
    domain {
        Aggregate LoanApplication {
            applicationId: UUID @identity
            applicantId: String @required
            requestedAmount: Decimal @min(1000)
            creditScore: Int @min(300) @max(850)
            status: String @default("DRAFT")
            submittedAt: DateTime?
            approvedAt: DateTime?

            state machine for status {
                states:
                    - DRAFT (initial)
                    - SUBMITTED
                    - APPROVED (final)
                    - REJECTED (final)
                    - WITHDRAWN (final)

                transitions:
                    - DRAFT -> SUBMITTED: when applicant data is complete
                    - SUBMITTED -> APPROVED: only when creditScore is greater than 650
                    - SUBMITTED -> REJECTED: when risk is too high
                    - [DRAFT, SUBMITTED] -> WITHDRAWN: always
            }

            operations {
                when submitting application with submittedAt:
                require that:
                    - applicantId is not empty
                    - requestedAmount is not empty
                    - creditScore is not empty
                then:
                    - set status to "SUBMITTED"
                    - set submittedAt to submittedAt
                emit LoanApplicationSubmitted with applicationId

                when approving application with approvedAt:
                require that:
                    - status is "SUBMITTED"
                    - creditScore is greater than 650
                    - requestedAmount is greater than 0
                then:
                    - set status to "APPROVED"
                    - set approvedAt to approvedAt
                emit LoanApplicationApproved with applicationId
            }
        }
    }

    events {
        DomainEvent LoanApplicationSubmitted {
            applicationId: UUID
            submittedAt: DateTime
        }

        DomainEvent LoanApplicationApproved {
            applicationId: UUID
            approvedAt: DateTime
        }
    }

    repositories {
        Repository LoanApplicationRepository for LoanApplication {
            findById(id: UUID): LoanApplication?
            save(application: LoanApplication): Void
        }
    }

    specifications {
        Specification ApprovableLoan {
            matches LoanApplication where:
                - status is "SUBMITTED"
                - creditScore is greater than 650
        }
    }
}

BoundedContext Returns {
    domain {
        Aggregate ReturnRequest {
            returnId: UUID @identity
            orderId: UUID @required
            customerId: String @required
            items: List<ReturnLine>
            reason: String @required
            status: String @default("REQUESTED")
            requestedAt: DateTime
            inspectedAt: DateTime?
            refundAmount: Money

            Entity ReturnLine {
                returnLineId: UUID @identity
                productId: String @required
                quantity: Int @min(1)
                condition: String @required
                lineRefund: Money
            }

            operations {
                when approving return with inspectedAt:
                require that:
                    - status is "REQUESTED"
                    - all items have quantity greater than 0
                    - reason is not empty
                then:
                    - calculate refundAmount as sum of line refunds
                    - set status to "APPROVED"
                    - set inspectedAt to inspectedAt
                emit ReturnApproved with returnId

                when rejecting return with rejectionReason:
                require that:
                    - status is "REQUESTED"
                    - rejectionReason is not empty
                then:
                    - set status to "REJECTED"
                emit ReturnRejected with returnId and rejectionReason
            }
        }

        ValueObject Money {
            amount: Decimal @min(0)
            currency: String @required @maxLength(3)
        }
    }

    events {
        DomainEvent ReturnApproved {
            returnId: UUID
            refundAmount: Money
            approvedAt: DateTime
        }

        DomainEvent ReturnRejected {
            returnId: UUID
            rejectionReason: String
            rejectedAt: DateTime
        }
    }

    repositories {
        Repository ReturnRequestRepository for ReturnRequest {
            findById(id: UUID): ReturnRequest?
            findByOrderId(orderId: UUID): List<ReturnRequest>
            save(returnRequest: ReturnRequest): Void
        }
    }
}

BoundedContext Support {
    domain {
        Aggregate Ticket {
            ticketId: UUID @identity
            customerId: String @required
            priority: String @required
            subject: String @required @maxLength(200)
            status: String @default("OPEN")
            createdAt: DateTime @required
            firstResponseDueAt: DateTime
            resolvedAt: DateTime?
            messages: List<TicketMessage>

            Entity TicketMessage {
                messageId: UUID @identity
                authorId: String @required
                body: String @required
                createdAt: DateTime @required
            }

            operations {
                when assigning ticket with agentId:
                require that:
                    - status is "OPEN"
                    - agentId is not empty
                then:
                    - set status to "ASSIGNED"
                emit TicketAssigned with ticketId and agentId

                when resolving ticket with resolvedAt:
                require that:
                    - status is one of "ASSIGNED", "IN_PROGRESS"
                    - messages is not empty
                    - resolvedAt is after createdAt
                then:
                    - set status to "RESOLVED"
                    - set resolvedAt to resolvedAt
                emit TicketResolved with ticketId
            }
        }

        DomainService SlaPolicy {
            when calculating first response due with priority as String and createdAt as DateTime:
            then:
                - calculate firstResponseDueAt as createdAt plus priority duration
        }
    }

    events {
        DomainEvent TicketAssigned {
            ticketId: UUID
            agentId: String
            assignedAt: DateTime
        }

        DomainEvent TicketResolved {
            ticketId: UUID
            resolvedAt: DateTime
        }
    }

    specifications {
        Specification OverdueTicket {
            matches Ticket where:
                - firstResponseDueAt is before now
                - status is not "RESOLVED"
        }
    }
}

BoundedContext Learning {
    domain {
        Aggregate CourseOffering {
            offeringId: UUID @identity
            courseCode: String @required
            instructorId: String @required
            capacity: Int @min(1)
            enrolledStudents: Set<StudentEnrollment>
            waitlistedStudents: List<StudentEnrollment>
            status: String @default("DRAFT")

            Entity StudentEnrollment {
                enrollmentId: UUID @identity
                studentId: String @required
                enrolledAt: DateTime @required
                status: String
            }

            operations {
                when publishing offering:
                require that:
                    - courseCode is not empty
                    - instructorId is not empty
                    - capacity is not empty
                then:
                    - set status to "PUBLISHED"

                when enrolling student with studentId and enrolledAt:
                require that:
                    - status is "PUBLISHED"
                    - studentId is not empty
                    - enrolledStudents is less than capacity
                then:
                    - create StudentEnrollment with studentId and enrolledAt
                    - add StudentEnrollment to enrolledStudents
                emit StudentEnrolled with offeringId and studentId

                when waitlisting student with studentId and enrolledAt:
                require that:
                    - status is "PUBLISHED"
                    - enrolledStudents is greater than capacity
                then:
                    - create StudentEnrollment with studentId and enrolledAt
                    - add StudentEnrollment to waitlistedStudents
                emit StudentWaitlisted with offeringId and studentId
            }
        }
    }

    events {
        DomainEvent StudentEnrolled {
            offeringId: UUID
            studentId: String
            enrolledAt: DateTime
        }

        DomainEvent StudentWaitlisted {
            offeringId: UUID
            studentId: String
            waitlistedAt: DateTime
        }
    }

    repositories {
        Repository CourseOfferingRepository for CourseOffering {
            findById(id: UUID): CourseOffering?
            findByCourseCode(courseCode: String): List<CourseOffering>
            save(offering: CourseOffering): Void
        }
    }

    specifications {
        Specification OpenForEnrollment {
            matches CourseOffering where:
                - status is "PUBLISHED"
                - enrolledStudents is less than capacity
        }
    }
}

BoundedContext Procurement {
    domain {
        Aggregate PurchaseOrder {
            purchaseOrderId: UUID @identity
            supplierId: String @required
            requesterId: String @required
            lines: List<PurchaseOrderLine>
            totalAmount: Money
            status: String @default("DRAFT")
            approvedAt: DateTime?

            Entity PurchaseOrderLine {
                lineId: UUID @identity
                itemCode: String @required
                quantity: Int @min(1)
                unitCost: Money @required
            }

            operations {
                when submitting purchase order:
                require that:
                    - supplierId is not empty
                    - requesterId is not empty
                    - lines is not empty
                then:
                    - calculate totalAmount as sum of line costs
                    - set status to "SUBMITTED"
                emit PurchaseOrderSubmitted with purchaseOrderId

                when approving purchase order with approvedAt and approverId:
                require that:
                    - status is "SUBMITTED"
                    - approverId is not empty
                    - totalAmount is greater than 0
                then:
                    - set status to "APPROVED"
                    - set approvedAt to approvedAt
                emit PurchaseOrderApproved with purchaseOrderId and approverId
            }
        }

        ValueObject Money {
            amount: Decimal @min(0)
            currency: String @required @maxLength(3)
        }

        DomainService ApprovalPolicy {
            when checking approval requirement with totalAmount as Money and requesterId as String:
            then:
                - calculate approvalRequired as totalAmount is greater than 1000
        }
    }

    events {
        DomainEvent PurchaseOrderSubmitted {
            purchaseOrderId: UUID
            submittedAt: DateTime
            total: Money
        }

        DomainEvent PurchaseOrderApproved {
            purchaseOrderId: UUID
            approverId: String
            approvedAt: DateTime
        }
    }

    factories {
        Factory PurchaseOrderFactory {
            when creating PurchaseOrder from supplierId with requesterId and lines:
            require that:
                - lines is not empty
            then:
                - create PurchaseOrder with supplierId and requesterId and lines
            return PurchaseOrder
        }
    }
}

BoundedContext Events {
    domain {
        Aggregate EventRegistration {
            registrationId: UUID @identity
            eventId: UUID @required
            attendeeEmail: String @required @email
            attendeeName: String @required
            ticketType: String @required
            status: String @default("RESERVED")
            expiresAt: DateTime
            checkedInAt: DateTime?

            operations {
                when reserving ticket with expiresAt:
                require that:
                    - attendeeEmail is not empty
                    - attendeeName is not empty
                    - eventId is not empty
                    - ticketType is not empty
                    - expiresAt is within next 30 days
                then:
                    - set status to "RESERVED"
                emit TicketReserved with registrationId and eventId

                when confirming registration:
                require that:
                    - status is "RESERVED"
                    - expiresAt is after now
                then:
                    - set status to "CONFIRMED"
                emit RegistrationConfirmed with registrationId

                when checking in with checkedInAt:
                require that:
                    - status is "CONFIRMED"
                    - checkedInAt is within last 1 days
                then:
                    - set status to "CHECKED_IN"
                    - set checkedInAt to checkedInAt
                emit AttendeeCheckedIn with registrationId
            }
        }
    }

    events {
        DomainEvent TicketReserved {
            registrationId: UUID
            eventId: UUID
            expiresAt: DateTime
        }

        DomainEvent RegistrationConfirmed {
            registrationId: UUID
            confirmedAt: DateTime
        }

        DomainEvent AttendeeCheckedIn {
            registrationId: UUID
            checkedInAt: DateTime
        }
    }

    repositories {
        Repository EventRegistrationRepository for EventRegistration {
            findById(id: UUID): EventRegistration?
            findByEventId(eventId: UUID): List<EventRegistration>
            findByAttendeeEmail(attendeeEmail: String): List<EventRegistration>
            save(registration: EventRegistration): Void
        }
    }

    specifications {
        Specification ExpiredReservation {
            matches EventRegistration where:
                - expiresAt is before now
                - status is "RESERVED"
        }

        Specification ConfirmedRegistration {
            matches EventRegistration where:
                - status is "CONFIRMED"
        }
    }
}
